{
  "story": "Clients and servers establish a reliable connection through a strict three-way sequence of packets, ensuring both sides acknowledge each other's initial sequence numbers before data transmission begins.",
  "aha": {
    "stateId": "ack",
    "observation": "The final ACK establishes that both client and server are synchronized and ready to exchange application data."
  },
  "layout": {
    "preset": "card",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.stepIndex",
        "items": "variant.states"
      }
    },
    {
      "id": "pic",
      "kind": "fixed-picture",
      "bind": {
        "active": "state.active",
        "links": "variant.links",
        "regions": "variant.regions"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "reason": "state.why",
        "target": "state.calloutRegion",
        "text": "state.sentence"
      }
    },
    {
      "id": "metrics",
      "kind": "value-readout",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "stepIndex",
      "kind": "index",
      "label": "Handshake Step",
      "options": [
        "SYN",
        "SYN-ACK",
        "ACK"
      ]
    },
    {
      "id": "resetBtn",
      "kind": "reset",
      "label": "Reset"
    }
  ],
  "data": {
    "variants": [
      {
        "label": "TCP Handshake",
        "regions": [
          {
            "id": "client",
            "label": "Client",
            "kind": "actor",
            "values": ["Port 5150", "State: Connecting"]
          },
          {
            "id": "server",
            "label": "Server",
            "kind": "actor",
            "values": ["Port 80", "State: Listening"]
          }
        ],
        "links": [
          {
            "from": "client",
            "to": "server",
            "label": "SYN Packet"
          },
          {
            "from": "server",
            "to": "client",
            "label": "SYN-ACK Packet"
          },
          {
            "from": "client",
            "to": "server",
            "label": "ACK Packet"
          }
        ],
        "states": [
          {
            "id": "syn",
            "label": "1. SYN",
            "short": "SYN",
            "sentence": "Client sends a SYN packet with an initial sequence number x.",
            "why": "Starts connection negotiation.",
            "active": ["client"],
            "calloutRegion": "client",
            "readouts": [
              {
                "id": "r1",
                "label": "Seq",
                "value": "x = 1000"
              },
              {
                "id": "r2",
                "label": "Flags",
                "value": "SYN"
              }
            ]
          },
          {
            "id": "synack",
            "label": "2. SYN-ACK",
            "short": "SYN-ACK",
            "sentence": "Server responds with SYN-ACK, acknowledging x and sending its own sequence y.",
            "why": "Confirms receipt and synchronizes server sequence.",
            "active": ["server"],
            "calloutRegion": "server",
            "readouts": [
              {
                "id": "r1",
                "label": "Seq",
                "value": "y = 5000"
              },
              {
                "id": "r2",
                "label": "Ack",
                "value": "x + 1 = 1001"
              }
            ]
          },
          {
            "id": "ack",
            "label": "3. ACK",
            "short": "ACK",
            "sentence": "Client sends final ACK confirming server sequence y, opening the connection.",
            "why": "Establishes bidirectional readiness.",
            "active": ["client", "server"],
            "calloutRegion": "client",
            "readouts": [
              {
                "id": "r1",
                "label": "Seq",
                "value": "x + 1 = 1001"
              },
              {
                "id": "r2",
                "label": "Ack",
                "value": "y + 1 = 5001"
              }
            ]
          }
        ]
      }
    ]
  }
}
